from pathlib import Path


def rep(path, old, new, count=1):
    p=Path(path); s=p.read_text()
    if old not in s: raise SystemExit(f'anchor missing {path}: {old[:100]!r}')
    p.write_text(s.replace(old,new,count))

# versions
for path in ['package.json','package-lock.json','server/package.json','server/package-lock.json']:
    p=Path(path); s=p.read_text(); p.write_text(s.replace('"version": "9.10.0"','"version": "9.16.0"',1))

